8	/**
9	 * Rejects creating an owner whose normalized telephone is already used by another owner.
10	 * The telephone on the built {@link Owner} has already been normalized by {@link BuildOwner}.
11	 */
12	public class EnsureUniqueTelephone {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
15	            throws DuplicateTelephoneException {
16	        boolean inUse = ownerRepository.findByTelephone(owner.getTelephone()).stream()
17	                .anyMatch(existing -> !existing.getId().equals(owner.getId()));
18	        if (inUse) {
19	            throw new DuplicateTelephoneException(
20	                    "An owner with telephone " + owner.getTelephone() + " already exists");
21	        }
22	    }
