1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
7	
8	/**
9	 * Rejects creating an owner when another owner already has the same last name and the same
10	 * address. The last name is compared case-insensitively with runs of whitespace collapsed to a
11	 * single space; the address is compared in its normalized form (see {@link Addresses}). The check
12	 * is skipped when the request set {@code sharesHousehold} true, which permits multiple owners in
13	 * one household.
14	 */
15	public class EnsureUniqueHousehold {
16	
17	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(sharesHousehold)) {
20	            return;
21	        }
22	        String lastName = normalize(owner.getLastName());
23	        String address = Addresses.normalize(owner.getAddress());
24	        boolean inHousehold = ownerRepository.findAll().stream()
25	                .filter(existing -> !existing.getId().equals(owner.getId()))
26	                .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
27	                        && Addresses.normalize(existing.getAddress()).equals(address));
28	        if (inHousehold) {
29	            throw new DuplicateHouseholdException(
30	                    "An owner named " + owner.getLastName() + " already exists at " + owner.getAddress());
31	        }
32	    }
33	
34	    private static String normalize(String value) {
35	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
36	    }
37	}
