1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners (as of this create,
9	 * before the new owner is saved) that share the same first name and last name, compared
10	 * case-insensitively. The new owner has not been persisted yet, so it is not counted.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = owner.getFirstName();
16	        String lastName = owner.getLastName();
17	        long count = ownerRepository.findAll().stream()
18	                .filter(existing -> !existing.getId().equals(owner.getId()))
19	                .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
20	                        && equalsIgnoreCase(existing.getLastName(), lastName))
21	                .count();
22	        owner.setNamesakeCount((int) count);
23	    }
24	
25	    private static boolean equalsIgnoreCase(String a, String b) {
26	        return a == null ? b == null : a.equalsIgnoreCase(b);
27	    }
28	}
