3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Shared handling for the owner {@code telephone}. Numbers are stored in E.164 form:
9	 * a leading {@code '+'} and country code are kept when present; otherwise country code
10	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
11	 * digits. Spaces, dashes and brackets are stripped, and the result must have 8 to 15
12	 * digits after the {@code '+'}.
13	 *
14	 * <p>So {@code '0412 345 678'} is stored as {@code '+61412345678'}.
15	 */
16	final class Telephones {
17	
18	    // Formatting characters allowed inside a supplied number: spaces, dashes and brackets.
19	    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");
20	
21	    // E.164: a '+' followed by 8 to 15 digits.
22	    private static final Pattern E164 = Pattern.compile("\\+\\d{8,15}");
23	
24	    private Telephones() {
25	    }
26	
27	    /**
28	     * Normalize a telephone to E.164 form.
29	     *
30	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
31	     */
32	    static String toE164(String telephone) throws InvalidTelephoneException {
33	        String stripped = SEPARATORS.matcher(telephone == null ? "" : telephone).replaceAll("");
34	        String e164;
35	        if (stripped.startsWith("+")) {
36	            // Keep the leading '+' and the country code exactly as supplied.
37	            e164 = stripped;
38	        }
39	        else {
40	            // No country code: assume '+61' and drop a single leading '0' from the national digits.
41	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
42	            e164 = "+61" + national;
43	        }
44	        if (!E164.matcher(e164).matches()) {
45	            throw new InvalidTelephoneException(
46	                    "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
47	        }
48	        return e164;
49	    }
50	}
