7	/**
8	 * Shared handling for the optional owner {@code email}. Email is optional, so a
9	 * blank or missing value is left untouched; when present it must be a syntactically
10	 * valid address and is stored lower-cased.
11	 */
12	final class OwnerEmails {
13	
14	    // Syntactic check: a non-empty local part, a single '@', and a dotted domain,
15	    // none of the parts containing whitespace or a stray '@'.
16	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
17	
18	    private OwnerEmails() {
19	    }
20	
21	    /**
22	     * Normalize an optional email. Returns {@code null}/blank unchanged; otherwise
23	     * validates syntax and returns the address lower-cased.
24	     *
25	     * @throws InvalidEmailException when a value is present but not syntactically valid.
26	     */
27	    static String normalize(String email) throws InvalidEmailException {
28	        if (email == null || email.isBlank()) {
29	            return email;
30	        }
31	        String trimmed = email.trim();
32	        if (!EMAIL.matcher(trimmed).matches()) {
33	            throw new InvalidEmailException("Email must be a syntactically valid address");
34	        }
35	        return trimmed.toLowerCase(java.util.Locale.ROOT);
36	    }
37	}
